<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('User/levellist')}">等级管理</a>                    <a href="{pigcms{:U('User/activation_code_list')}" class="on">激活码管理</a>                    <a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('User/add_activation_code')}','批量添加激活码',650,500,true,false,false,addbtn,'add',true);" style="margin-left:20px;">批量添加激活码</a>                    <a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('User/activation_mutil')}','批量操作（批量将激活码绑定到商家，请保证激活码存在）',680,560,true,false,false,addbtn,'edit',true);">批量操作</a>                    <a href="{pigcms{:U('User/activation_code_log')}">激活码操作记录</a>                </ul>			</div>			<table class="search_table" width="100%">				<tr>					<td>						<form action="{pigcms{:U('User/activation_code_list')}" method="get">							<input type="hidden" name="c" value="User"/>							<input type="hidden" name="a" value="activation_code_list"/>							筛选: <input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>							<select name="searchtype">                                <option value="code_id" <if condition="$_GET['searchtype'] eq 'code_id'">selected="selected"</if>>ID</option>                                <option value="activation_code" <if condition="$_GET['searchtype'] eq 'activation_code'">selected="selected"</if>>激活码</option>                                <option value="uid" <if condition="$_GET['searchtype'] eq 'uid'">selected="selected"</if>>用户ID</option>                                <option value="mer_id" <if condition="$_GET['searchtype'] eq 'mer_id'">selected="selected"</if>>商户ID</option>							</select>                            状态:                            <select name="status">                                <option value="-1" <if condition="$_GET['status'] eq '-1'">selected="selected"</if>>全部</option>                                <option value="-2" <if condition="$_GET['status'] eq '-2'">selected="selected"</if>>未激活</option>                                <option value="1" <if condition="$_GET['status'] eq '1'">selected="selected"</if>>激活</option>                                <option value="2" <if condition="$_GET['status'] eq '2'">selected="selected"</if>>禁用</option>                                <option value="3" <if condition="$_GET['status'] eq '3'">selected="selected"</if>>失效</option>                            </select>                            <font color="#000">日期筛选：</font>                            <input type="text" class="input-text" name="begin_time" style="width:120px;" id="d4311"  value="{pigcms{$_GET.begin_time}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>                            <input type="text" class="input-text" name="end_time" style="width:120px;" id="d4311" value="{pigcms{$_GET.end_time}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>                            <input type="submit" value="查询" class="button"/>                            <a href="javascript:void(0)" onclick="exports()" class="button" style="float:right;margin-right: 10px;">导出用户</a>						</form>					</td>				</tr>			</table>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>							<if condition="$config['level_balance']">								<col/>							</if>							<col width="180" align="center"/>						</colgroup>						<thead>							<tr>								<th width="50px">ID</th>								<th >激活码</th>								<th >用户ID</th>								<th >会员等级</th>								<th >商家ID</th>                                <th >激活时间</th>                                <th >最后修改时间</th>                                <th >状态</th>								<th>操作</th>							</tr>						</thead>						<tbody>							<if condition="is_array($list)">								<volist name="list" id="vo">									<tr>                                        <td>{pigcms{$vo.code_id}</td>                                        <td>{pigcms{$vo.activation_code}</td>                                        <td>                                            <if condition="$vo['uid'] gt 0">                                                {pigcms{$vo.uid} | <a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('User/edit',array('uid'=>$vo['uid'],'frame_show'=>true))}','查看用户信息',750,650,true,false,false,false,'user_detail',true);">查看用户信息</a>                                                <else/>                                                <span style="color: red;">没有绑定用户</span>                                            </if>                                        </td>										<td>{pigcms{$vo.lname}</td>                                        <td>{pigcms{$vo.mer_id}</td>                                        <td>                                            <if condition="$vo['activation_time'] gt 0">                                                {pigcms{$vo.activation_time|date="Y-m-d H:i:s",###}                                            </if>                                        </td>                                        <td>                                            <if condition="$vo['last_time'] gt 0">                                                {pigcms{$vo['last_time']|date="Y-m-d H:i:s",###}                                                <elseif condition="$vo['add_time'] gt 0"/>                                                {pigcms{$vo['add_time']|date="Y-m-d H:i:s",###}                                            </if>                                        </td>                                        <td>{pigcms{$status_info[$vo['status']]}</td>										<td>                                            <a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('User/edit_activation_code',array('code_id'=>$vo['code_id']))}','编辑等级信息',650,500,true,false,false,editbtn,'edit',true);">编 辑</a>                                            |                                            <a href="javascript:void(0);" class="delete_row"  tip="删除后绑定用户等级失效，是否确认删除？" parameter="code_id={pigcms{$vo['code_id']}" url="/admin.php?g=System&c=User&a=del_activation_code">删除</a>                                        </td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="9">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="9">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div><script>    var url = "{pigcms{$config.site_url}";    var export_url = "{pigcms{:U('User/activation_code_export')}";</script><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><include file="Public:footer"/>